<script setup>
import {onMounted,reactive,ref} from 'vue'
import {BookOpen,Plus,Users,ArrowRight,X} from '@lucide/vue'
import {auth,loadSession} from '../composables/auth'
import {experience} from '../composables/experience'
import {api} from '../api'
const courses=ref([]),loading=ref(true),error=ref(''),showForm=ref(false),busy=ref(false),form=reactive({code:'',title:'',termCode:''})
const roles={teacher:'授課教師',ta:'課程助教',student:'學生'}
async function load(){try{courses.value=await api('/courses')}catch(e){error.value=e.message}finally{loading.value=false}}
async function create(){busy.value=true;error.value='';try{await api('/courses',{method:'POST',body:form});Object.assign(form,{code:'',title:'',termCode:''});showForm.value=false;await loadSession(true);await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="page-heading"><div><p class="eyebrow">COURSE MANAGEMENT</p><h1>課程管理</h1><p class="muted">以課程集中管理資源、學員、案例、測驗、PDF 作業與成績。只顯示你實際參與的課程。</p></div><button v-if="auth.user.canCreateCourses && !experience.student" class="button primary" @click="showForm=!showForm"><Plus :size="17" />建立課程</button></section><p v-if="error" class="error-box" role="alert">{{error}}</p><section v-if="showForm" class="surface form-surface"><div class="section-title"><h2>建立課程</h2><button class="icon-button" aria-label="關閉建立課程" @click="showForm=false"><X :size="18" /></button></div><form @submit.prevent="create"><fieldset :disabled="busy"><div class="form-grid three"><label>課程代碼<input v-model="form.code" required maxlength="40" /></label><label>課程名稱<input v-model="form.title" required maxlength="200" /></label><label>學期代碼<input v-model="form.termCode" required maxlength="40" /></label></div><p class="field-hint">建立者成為課程擁有者；進入課程後可安排學員與相關評量。</p><button class="button primary">儲存課程</button></fieldset></form></section><p v-if="loading" class="empty-inline">載入課程中…</p><section v-else-if="!courses.length" class="surface course-empty"><BookOpen :size="32" /><h2>目前尚無參與課程</h2><p>具有建課資格的成員可建立課程；其他成員請聯絡課程擁有者安排加入。</p></section><div v-else class="course-grid"><article v-for="course in courses" :key="course.id" class="surface course-card"><div class="course-card-top"><span class="course-emblem"><BookOpen :size="24" /></span><span class="status-badge">{{{draft:'草稿',active:'進行中',archived:'已封存'}[course.status]}}</span></div><span class="eyebrow">{{course.code}} · {{course.termCode}}</span><h2>{{course.title}}</h2><p class="muted">{{roles[course.courseRole]}}<span v-if="course.isOwner"> · 課程擁有者</span></p><div class="course-meta"><span><Users :size="15" />{{course.studentCount}} 位學員</span><span>{{course.resourceCount}} 份資源</span></div><p class="field-hint">{{course.quizCount}} 份測驗 · {{course.reportCount}} 份 PDF 作業</p><RouterLink :to="`/courses/${course.id}`" class="button primary course-open-link">進入課程 <ArrowRight :size="16" /></RouterLink></article></div></template>
